(ns clojure-algorithms.maths.recursive-digit-sum
  "The super digit problem is defined as follows:\nGiven an integer n represented as a string and an integer k,\nthe goal is to find the super digit of the number formed by concatenating\nthe integer n k times.\n\nThe super digit of a number is defined recursively:\n- If the number has only one digit, that digit is the super digit.\n- Otherwise, the super digit is the super digit of the sum of its digits.\n\nFor example, for n = \"9875\" and k = 4, the concatenated number is:\nsuper_digit(9875987598759875), which can be reduced by summing its digits."
  (:require [clojure-algorithms.runtime.python :refer :all] [clojure.string :as str]))

(declare super-digit)

(defn super-digit "Computes the super digit of a number formed by concatenating\nn_str repeated times.\n\nParameters:\nn_str (str): The string representation of the integer.\nrepetitions (int): The number of times to concatenate n_str.\n\nReturns:\nint: The super digit of the concatenated number.\n\n>>> super_digit(\"148\", 3)\n3\n>>> super_digit(\"9875\", 4)\n8\n>>> super_digit(\"123\", 3)\n9"
  [n-str repetitions] (let [digit-sum (atom nil) total-sum (atom nil)] (try (reset! digit-sum (reduce +' 0 (doall (for [digit (py-iter n-str)] (py-int digit nil))))) (reset! total-sum (py-mul @digit-sum repetitions)) (while (py-truthy (py-ge @total-sum 10)) (reset! total-sum (reduce +' 0 (doall (for [digit (py-iter (py-str @total-sum))] (py-int digit nil)))))) (throw (ex-info "__return__" {:__control__ true :__return__ true :value @total-sum})) (catch clojure.lang.ExceptionInfo __e (if (:__return__ (ex-data __e)) (:value (ex-data __e)) (throw __e))))))
